      statusCodes: {
        success: 200,
      },
    },
    getDepartmentTypes: {
      method: "GET",
      path: "/api/v1/reference/departments",
      statusCodes: {
        success: 200,
      },
    },
    getRoleDepartmentMappings: {
      method: "GET",
