}


provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}


output "alb_dns_name" {
  value       = module.alb.alb_dns_name
  description = "ALB DNS name"
}

output "fastapi_direct_endpoint" {
  value       = "http://${module.alb.alb_dns_name}:8000"
