def fetch_parameters(path_prefix):
    """Fetch all parameters from SSM under the given path prefix."""
    params = {}
    next_token = None
    while True:
        kwargs = {
            "Path": path_prefix,
            "Recursive": True,
            "WithDecryption": True,
            "MaxResults": 10
        }
        if next_token:
            kwargs["NextToken"] = next_token

        response = ssm.get_parameters_by_path(**kwargs)
        for p in response.get("Parameters", []):
            # Take the last segment of the name as the key
            key = p["Name"].split("/")[-1]
            params[key] = p["Value"]

        next_token = response.get("NextToken")
        if not next_token:
            break

    return params

def get_public_key(kid):
    for key in get_jwks():
        if key["kid"] == kid:
            return key
    raise HTTPException(status_code=401, detail="Invalid token header")

def verify_cognito_jwt(token: str):
    if token.startswith("Bearer "):
        token = token.split(" ")[1]

    try:
        headers = jwt.get_unverified_header(token)
        key = get_public_key(headers["kid"])

        payload = jwt.decode(
            token,
            key,
            algorithms=["RS256"],
            audience=settings.COGNITO_APP_CLIENT_ID,
            issuer=settings.ISSUER,
        )

        return payload

    except ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")

    except JWTError as e:
        raise HTTPException(status_code=401, detail=f"Invalid JWT: {str(e)}")

def require_group(group_name: str):
    def checker(request: Request):
        user = request.state.user
        if user is None:
            raise HTTPException(status_code=401, detail="Unauthorized: missing token")

        groups = user.get("cognito:groups", [])
        if group_name not in groups:
            raise HTTPException(status_code=403, detail="Forbidden: missing permissions")
        return user
    return checker

