def _raise_for_github_error(response: httpx.Response, owner: str, repo: str) -> None:
    """Translate common GitHub API error codes into meaningful HTTP exceptions."""
    if response.status_code == 200:
        return
    if response.status_code == 401:
        raise HTTPException(
            status_code=401,
            detail="GitHub token is invalid or expired. Please reconnect your GitHub account.",
        )
    if response.status_code == 403:
        raise HTTPException(
            status_code=403,
            detail="Access denied by GitHub. Check repository permissions.",
        )
    if response.status_code == 404:
        raise HTTPException(
            status_code=404,
            detail=f"Repository '{owner}/{repo}' not found or you do not have access.",
        )
    raise HTTPException(
        status_code=502,
        detail=f"Unexpected response from GitHub API: {response.status_code}",
    )

def extract_symbols(file_path: str, content: str) -> list[dict[str, Any]]:
    """
    Parse *content* and return a list of symbol dicts.

    Each dict has the keys expected by RepositoryFunctionRepository.replace_for_repo:
        name, qualified_name, symbol_type, parameters (JSON str), return_type,
        docstring, line_start, line_end, class_name, is_async, source_code
    """
    ext = Path(file_path).suffix.lower()
    try:
        if ext == ".py":
            return _extract_python(content)
        if ext in (".ts", ".tsx", ".js", ".jsx"):
            return _extract_js_ts(content)
    except Exception:
        logger.debug("Symbol extraction failed | file=%s", file_path, exc_info=True)
    return []

def _extract_python(content: str) -> list[dict[str, Any]]:
    try:
        tree = ast.parse(content)
    except SyntaxError:
        return []

    symbols: list[dict[str, Any]] = []
    _visit_python_node(tree, symbols, class_name=None, content=content)
    return symbols

def _py_params(node: ast.FunctionDef | ast.AsyncFunctionDef) -> list[dict]:
    params = []
    args = node.args
    # Build default offset: last N positional args may have defaults
    n_defaults = len(args.defaults)
    all_args = args.posonlyargs + args.args
    default_offset = len(all_args) - n_defaults

    for i, arg in enumerate(all_args):
        default_val = None
        if i >= default_offset:
            d = args.defaults[i - default_offset]
            try:
                default_val = ast.unparse(d)
            except Exception:
                default_val = "..."

        annotation = None
        if arg.annotation:
            try:
                annotation = ast.unparse(arg.annotation)
            except Exception:
                pass

        params.append({"name": arg.arg, "type": annotation, "default": default_val})

    # *args
    if args.vararg:
        annotation = None
        if args.vararg.annotation:
            try:
                annotation = ast.unparse(args.vararg.annotation)
            except Exception:
                pass
        params.append({"name": f"*{args.vararg.arg}", "type": annotation, "default": None})

    # **kwargs
    if args.kwarg:
        annotation = None
        if args.kwarg.annotation:
            try:
                annotation = ast.unparse(args.kwarg.annotation)
            except Exception:
                pass
        params.append({"name": f"**{args.kwarg.arg}", "type": annotation, "default": None})

    return params

def _py_return_type(node: ast.FunctionDef | ast.AsyncFunctionDef) -> str | None:
    if node.returns:
        try:
            return ast.unparse(node.returns)
        except Exception:
            pass
    return None

class SymbolExtractionService:
    def __init__(self, db: AsyncSession) -> None:
        self.db = db
        self.file_repo = RepositoryFileRepository(db)
        self.func_repo = RepositoryFunctionRepository(db)
        self.call_repo = FunctionCallRepository(db)

    async def extract_and_store_symbols(
        self,
        connected_repo_id: uuid.UUID,
        file_contents: dict[str, str],
    ) -> int:
        files: List[RepositoryFile] = await self.file_repo.get_by_repo(connected_repo_id)
        total = 0

        for f in files:
            if f.is_binary or f.extension not in PARSEABLE:
                continue
            content = file_contents.get(f.path)
            if not content:
                continue

            symbols = extract_symbols(f.path, content)
            if not symbols:
                continue

            await self.func_repo.replace_for_repo(connected_repo_id, f.id, symbols)
            total += len(symbols)
            logger.debug("Symbols extracted | file=%s count=%d", f.path, len(symbols))

        logger.info(
            "Symbol extraction complete | repo=%s total_symbols=%d",
            connected_repo_id,
            total,
        )
        return total

    async def build_call_graph(
        self,
        connected_repo_id: uuid.UUID,
        file_contents: dict[str, str],
    ) -> int:
        all_funcs: List[RepositoryFunction] = await self.func_repo.get_by_repo(connected_repo_id)

        name_to_funcs: dict[str, list[RepositoryFunction]] = {}
        for fn in all_funcs:
            name_to_funcs.setdefault(fn.name, []).append(fn)

        qname_to_func: dict[str, RepositoryFunction] = {
            fn.qualified_name: fn for fn in all_funcs if fn.qualified_name
        }

        known_names: set[str] = set(name_to_funcs.keys())

        files: List[RepositoryFile] = await self.file_repo.get_by_repo(connected_repo_id)

        edges: list[dict] = []

        for f in files:
            if f.is_binary or f.extension not in PARSEABLE:
                continue
            content = file_contents.get(f.path)
            if not content:
                continue

            raw_calls = extract_calls(f.path, content, known_names)

            for caller_qname, callee_name, call_line in raw_calls:
                caller_fn: RepositoryFunction | None = qname_to_func.get(caller_qname)
                if caller_fn is None:
                    candidates = name_to_funcs.get(caller_qname, [])
                    same_file = [c for c in candidates if c.file_id == f.id]
                    caller_fn = same_file[0] if same_file else (candidates[0] if candidates else None)

                if caller_fn is None:
                    continue

                callee_candidates = name_to_funcs.get(callee_name, [])
                if not callee_candidates:
                    continue
                same_file_callee = [c for c in callee_candidates if c.file_id == f.id]
                callee_fn: RepositoryFunction = same_file_callee[0] if same_file_callee else callee_candidates[0]

                if callee_fn.id == caller_fn.id:
                    continue

                edges.append(
                    {
                        "connected_repo_id": connected_repo_id,
                        "source_function_id": caller_fn.id,
                        "target_function_id": callee_fn.id,
                        "call_line": call_line,
                    }
                )

        seen: set[tuple] = set()
        deduped = []
        for e in edges:
            key = (e["source_function_id"], e["target_function_id"])
            if key not in seen:
                seen.add(key)
                deduped.append(e)

        await self.call_repo.replace_for_repo(connected_repo_id, deduped)
        logger.info(
            "Call graph built | repo=%s edges=%d",
            connected_repo_id,
            len(deduped),
        )
        return len(deduped)

async def build_call_graph(
    self,
    connected_repo_id: uuid.UUID,
    file_contents: dict[str, str],
) -> int:
    all_funcs: List[RepositoryFunction] = await self.func_repo.get_by_repo(connected_repo_id)

    name_to_funcs: dict[str, list[RepositoryFunction]] = {}
    for fn in all_funcs:
        name_to_funcs.setdefault(fn.name, []).append(fn)

    qname_to_func: dict[str, RepositoryFunction] = {
        fn.qualified_name: fn for fn in all_funcs if fn.qualified_name
    }

    known_names: set[str] = set(name_to_funcs.keys())

    files: List[RepositoryFile] = await self.file_repo.get_by_repo(connected_repo_id)

    edges: list[dict] = []

    for f in files:
        if f.is_binary or f.extension not in PARSEABLE:
            continue
        content = file_contents.get(f.path)
        if not content:
            continue

        raw_calls = extract_calls(f.path, content, known_names)

        for caller_qname, callee_name, call_line in raw_calls:
            caller_fn: RepositoryFunction | None = qname_to_func.get(caller_qname)
            if caller_fn is None:
                candidates = name_to_funcs.get(caller_qname, [])
                same_file = [c for c in candidates if c.file_id == f.id]
                caller_fn = same_file[0] if same_file else (candidates[0] if candidates else None)

            if caller_fn is None:
                continue

            callee_candidates = name_to_funcs.get(callee_name, [])
            if not callee_candidates:
                continue
            same_file_callee = [c for c in callee_candidates if c.file_id == f.id]
            callee_fn: RepositoryFunction = same_file_callee[0] if same_file_callee else callee_candidates[0]

            if callee_fn.id == caller_fn.id:
                continue

            edges.append(
                {
                    "connected_repo_id": connected_repo_id,
                    "source_function_id": caller_fn.id,
                    "target_function_id": callee_fn.id,
                    "call_line": call_line,
                }
            )

    seen: set[tuple] = set()
    deduped = []
    for e in edges:
        key = (e["source_function_id"], e["target_function_id"])
        if key not in seen:
            seen.add(key)
            deduped.append(e)

    await self.call_repo.replace_for_repo(connected_repo_id, deduped)
    logger.info(
        "Call graph built | repo=%s edges=%d",
        connected_repo_id,
        len(deduped),
    )
    return len(deduped)

