class UserContextMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        if request.url.path in PUBLIC_PATHS:
            request.state.user = None
            request.state.db = None
            return await call_next(request)

        auth_header = request.headers.get("authorization")
        if not auth_header or not auth_header.startswith("Bearer "):
            return JSONResponse(
                status_code=401,
                content={"detail": "Missing or invalid Authorization header"},
            )
        token = auth_header.split(" ", 1)[1]

        try:
            claims = decode_access_token(token)
        except JWTError:
            return JSONResponse(
                status_code=401,
                content={"detail": "Invalid or expired token"},
            )

        subject = claims.get("sub")
        if not subject:
            return JSONResponse(
                status_code=401,
                content={"detail": "Invalid token claims"},
            )

        if (
            hasattr(request.app.state, "test_db_session")
            and request.app.state.test_db_session is not None
        ):
            db = request.app.state.test_db_session
            request.state.db = db
            should_close_db = False
        elif hasattr(request.state, "db") and request.state.db is not None:
            db = request.state.db
            should_close_db = False
        else:
            db_gen = get_db()
            db: AsyncSession = await db_gen.__anext__()
            request.state.db = db
            should_close_db = True

        try:
            result = await db.execute(
                select(User).where(User.id == uuid.UUID(subject))
            )
            db_user = result.scalar_one_or_none()

            if not db_user:
                logger.warning(f"User {subject} from token not found in database")
                return JSONResponse(
                    status_code=401,
                    content={"detail": "User no longer exists"},
                )

            enriched_user = EnrichedUserContext(claims, db_user)
            request.state.user = enriched_user
            logger.debug(f"User context: {enriched_user.to_dict()}")

            return await call_next(request)

        except HTTPException as e:
            logger.warning(f"Auth error: {e.detail}")
            return JSONResponse(status_code=e.status_code, content={"detail": e.detail})
        except SQLAlchemyError as e:
            logger.error(f"Database error: {str(e)}")
            return JSONResponse(status_code=500, content={"detail": "Internal database error"})
        except (ValueError, ValidationError) as e:
            logger.error(f"Validation error: {str(e)}")
            return JSONResponse(status_code=422, content={"detail": str(e)})
        except Exception as e:
            logger.error(f"Unexpected error: {str(e)}", exc_info=True)
            return JSONResponse(status_code=500, content={"detail": "Internal server error"})
        finally:
            if should_close_db:
                await db_gen.aclose()

