  for (const path of paths) {
    try {
      const url = `${baseUrl}${path}`;
      console.log(`   Trying: ${url}`);
      const data = await fetchUrl(url);
      return JSON.parse(data);
    } catch (error) {
      if (paths.indexOf(path) === paths.length - 1) throw error;
